/*
 * A232866  Positions of the nonnegative integers in the sequence (or tree) of
 *          complex numbers generated by these rules: 0 is in S, and if x is
 *          in S, then x + 1 and i*x are in S, where duplicates are deleted as
 *          they occur.
 * https://oeis.org/A232866
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy
 * Formula:   a(1)=1, a(2)=2, a(3)=3, a(4)=5; for n≥5: a(n)=2*(n-4)^2 + (n-4)
 *            + 6
 * Range:     u8 n <= 14, u16 n <= 184, u32 n <= 1000, u64 n <= 1000,
 *            u128 n <= 1000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

seq_t a(idx_t n)
{
    /* trivial base cases */
    if (n == 1) return 1;
    if (n == 2) return 2;
    if (n == 3) return 3;
    if (n == 4) return 5;

    /* use the proven closed form for n≥5 */
    /* seq_t represents an unsigned integer type of sufficient size */
    seq_t m = (seq_t)(n - 4);          /* m = n-4 in seq_t form */
    return 2 * m * m + m + 6;          /* 2*(n-4)^2 + (n-4) + 6 */
}
